//! Blackbody colours: a temperature in kelvin to a display colour, for views that draw hot
//! things (an accretion disk, stars).
//!
//! `TABLE` holds linear sRGB, normalized so the brightest channel is 1, at 256 temperatures
//! spaced geometrically from 1000 K to 40000 K (colour changes fastest when it is cold). It is
//! generated by the test `print_blackbody_table`: Planck's law integrated against the CIE 1931
//! 2-degree observer (the multi-lobe fit of Wyman, Sloan and Shirley, 2013, JCGT 2(2)), then the
//! IEC 61966-2-1 matrix to linear sRGB with negative channels clipped. To regenerate it, run
//!
//! ```sh
//! cargo test print_blackbody_table -- --ignored --nocapture
//! ```
//!
//! and paste the output over `TABLE`. A test fails when the constants and the generator differ.
//! There is no chromatic adaptation: the colour is that of the light itself, white point and all.

use crate::render::Color;

/// Coldest tabulated temperature in kelvin.
pub const MINIMUM_KELVIN: f32 = 1000.0;
/// Hottest tabulated temperature in kelvin.
pub const MAXIMUM_KELVIN: f32 = 40000.0;

