/// Linear sRGB of a blackbody at `kelvin`, clamped to 1000 K to 40000 K and interpolated linearly
/// in `ln T` between neighbouring entries. The brightest channel is 1.
#[cfg_attr(
    not(test),
    expect(dead_code, reason = "no caller until the first view that uses it")
)]
pub fn linear(kelvin: f32) -> [f32; 3] {
    let last = TABLE.len() - 1;
    let span = (MAXIMUM_KELVIN / MINIMUM_KELVIN).ln();
    let kelvin = if kelvin.is_nan() {
        MINIMUM_KELVIN
    } else {
        kelvin.clamp(MINIMUM_KELVIN, MAXIMUM_KELVIN)
    };
    let position = ((kelvin / MINIMUM_KELVIN).ln() / span * last as f32).clamp(0.0, last as f32);
    let lower = (position.floor() as usize).min(last - 1);
    let fraction = position - lower as f32;
    let (cold, hot) = (TABLE[lower], TABLE[lower + 1]);
    std::array::from_fn(|channel| cold[channel] + (hot[channel] - cold[channel]) * fraction)
}

/// The sRGB-encoded colour of a blackbody at `kelvin`, scaled in linear light by `brightness`
/// (clamped to 0 to 1). Frames hold encoded bytes, so this is what a view draws with.
#[cfg_attr(
    not(test),
    expect(dead_code, reason = "no caller until the first view that uses it")
)]
pub fn color(kelvin: f32, brightness: f32) -> Color {
    let brightness = if brightness.is_nan() {
        0.0
    } else {
        brightness.clamp(0.0, 1.0)
    };
    linear(kelvin).map(|channel| encode(channel * brightness))
}

/// The sRGB transfer function, rounded to a byte.
fn encode(linear: f32) -> u8 {
    let linear = linear.clamp(0.0, 1.0);
    let encoded = if linear < 0.003_130_8 {
        12.92 * linear
    } else {
        1.055 * linear.powf(1.0 / 2.4) - 0.055
    };
    (encoded * 255.0).round() as u8
}

#[cfg(test)]
mod tests {
    use super::*;

    /// Entry `index` of the table, computed from scratch in `f64`.
    fn generated() -> Vec<[f64; 3]> {
        // Wyman, Sloan and Shirley's piecewise Gaussian lobe, in nanometres.
        let lobe = |wavelength: f64, mean: f64, below: f64, above: f64| {
            let width = if wavelength < mean { below } else { above };
            (-0.5 * ((wavelength - mean) / width).powi(2)).exp()
        };
        let matching = |wavelength: f64| {
            let x = 1.056 * lobe(wavelength, 599.8, 37.9, 31.0)
                + 0.362 * lobe(wavelength, 442.0, 16.0, 26.7)
                - 0.065 * lobe(wavelength, 501.1, 20.4, 26.2);
            let y = 0.821 * lobe(wavelength, 568.8, 46.9, 40.5)
                + 0.286 * lobe(wavelength, 530.9, 16.3, 31.1);
            let z = 1.217 * lobe(wavelength, 437.0, 11.8, 36.0)
                + 0.681 * lobe(wavelength, 459.0, 26.0, 13.8);
            [x, y, z]
        };
        let second_radiation_constant = 1.438_776_9e-2;
        (0..256)
            .map(|index| {
                let kelvin = 1000.0 * 40.0_f64.powf(index as f64 / 255.0);
                let mut xyz = [0.0; 3];
                for nanometres in 360..=830 {
                    let wavelength = f64::from(nanometres);
                    let meters = wavelength * 1e-9;
                    let radiance = meters.powi(-5)
                        / ((second_radiation_constant / (meters * kelvin)).exp() - 1.0);
                    let weights = matching(wavelength);
                    for channel in 0..3 {
                        xyz[channel] += radiance * weights[channel];
                    }
                }
                let [x, y, z] = xyz;
                let mut rgb = [
                    3.2406 * x - 1.5372 * y - 0.4986 * z,
                    -0.9689 * x + 1.8758 * y + 0.0415 * z,
                    0.0557 * x - 0.2040 * y + 1.0570 * z,
                ];
                rgb = rgb.map(|channel: f64| channel.max(0.0));
                let brightest = rgb.iter().copied().fold(0.0, f64::max);
                rgb.map(|channel| channel / brightest)
            })
            .collect()
    }

    #[test]
    #[ignore = "prints the table; run it to regenerate TABLE"]
    fn print_blackbody_table() {
        for [red, green, blue] in generated() {
            println!("    [{red:.6}, {green:.6}, {blue:.6}],");
        }
    }

    #[test]
    fn blackbody_table_matches_its_generator() {
        for (index, (expected, entry)) in generated().iter().zip(TABLE).enumerate() {
            for channel in 0..3 {
                let difference = (expected[channel] - f64::from(entry[channel])).abs();
                assert!(
                    difference <= 1e-5,
                    "entry {index} channel {channel}: {} against {}",
                    expected[channel],
                    entry[channel]
                );
            }
        }
    }

    #[test]
    fn blackbody_colours_match_published_values() {
        // Mitchell Charity, "What color is a blackbody?", CIE 1931 2-degree observer:
        // http://www.vendian.org/mncharity/dir3/blackbody/
        let within: [(f32, [u8; 3]); 6] = [
            (2000.0, [255, 137, 18]),
            (3000.0, [255, 180, 107]),
            (5000.0, [255, 228, 206]),
            (6500.0, [255, 249, 253]),
            (10000.0, [202, 218, 255]),
            (20000.0, [168, 192, 255]),
        ];
        for (kelvin, published) in within {
            let actual = color(kelvin, 1.0);
            for channel in 0..3 {
                assert!(
                    actual[channel].abs_diff(published[channel]) <= 6,
                    "{kelvin} K: {actual:?} against {published:?}"
                );
            }
        }
        // The published table is chromatically adapted and ours is not, so its green channel
        // differs by more than 6 levels at the ends (9 and 8). Pinned, not tolerated: a change
        // to the generator moves these rows and fails here.
        let outside: [(f32, [u8; 3], [u8; 3]); 2] = [
            (1000.0, [255, 56, 0], [255, 47, 0]),
            (40000.0, [155, 176, 255], [158, 184, 255]),
        ];
        for (kelvin, published, ours) in outside {
            assert_eq!(
                color(kelvin, 1.0),
                ours,
                "{kelvin} K, published {published:?}"
            );
        }
    }

    #[test]
    fn blackbody_lookup_clamps_and_interpolates_in_log_temperature() {
        assert_eq!(linear(10.0), TABLE[0]);
        assert_eq!(linear(1000.0), TABLE[0]);
        assert_eq!(linear(40000.0), TABLE[255]);
        assert_eq!(linear(1.0e6), TABLE[255]);
        assert_eq!(linear(f32::NAN), TABLE[0]);
        for index in [0, 17, 100, 254] {
            let kelvin = 1000.0 * 40.0_f32.powf((index as f32 + 0.5) / 255.0);
            let middle = linear(kelvin);
            for channel in 0..3 {
                let mean = (TABLE[index][channel] + TABLE[index + 1][channel]) / 2.0;
                assert!(
                    (middle[channel] - mean).abs() < 1e-4,
                    "index {index} channel {channel}: {} against {mean}",
                    middle[channel]
                );
            }
        }
    }

    #[test]
    fn hotter_blackbodies_are_bluer() {
        let ratio = |entry: [f32; 3]| entry[2] / entry[0];
        // The coldest entries have a negative blue channel in the fit, which the clip sets to 0.
        for pair in TABLE.windows(2) {
            if pair[1][2] > 0.0 {
                assert!(ratio(pair[1]) > ratio(pair[0]), "{pair:?}");
            } else {
                assert!(ratio(pair[1]) >= ratio(pair[0]), "{pair:?}");
            }
        }
        assert_eq!(TABLE[0][0], 1.0);
        assert!(TABLE[0][2] < 0.01);
        assert_eq!(TABLE[255][2], 1.0);
        for entry in TABLE {
            assert_eq!(entry.iter().copied().fold(0.0, f32::max), 1.0);
        }
    }

    #[test]
    fn blackbody_colour_applies_brightness_and_srgb_encoding() {
        assert_eq!(color(5000.0, 0.0), [0, 0, 0]);
        assert_eq!(color(5000.0, -1.0), [0, 0, 0]);
        assert_eq!(color(5000.0, 7.0), color(5000.0, 1.0));
        assert_eq!(encode(0.5), 188);
        assert_eq!(encode(0.0), 0);
        assert_eq!(encode(1.0), 255);
        assert_eq!(color(1000.0, 1.0)[0], 255);
        assert_eq!(color(1000.0, 0.5)[0], 188);
    }
}
